// Generated by _shared/build.py: Cloudflare Pages guard. Serves only live Cloudflare creators
// (minus their notes) plus shared assets, whatever the dashboard build settings are, so the
// research notes, content.json and repo files are never public even if the repo root is deployed.
//
// Visit alerts: when a real person opens a pitch page or one of its deliverables, a message goes to the
// owner's Discord channel (webhook) and/or Telegram bot, whichever is configured. The secrets live in
// Cloudflare (Pages → Settings → Variables and Secrets: DISCORD_WEBHOOK_URL, or TELEGRAM_BOT_TOKEN +
// TELEGRAM_CHAT_ID), never in this public repo; without them nothing is sent. Link-preview bots,
// prefetches and the owner's own devices (opened once with ?me=1, which sets a cookie) are skipped.
// Self-test: ?alerttest=<Discord webhook id or Telegram chat id> sends one message to every configured
// channel and reports the answers in the x-alert-result header. (ntfy.sh was tried first: its free tier
// limits per IP, and Cloudflare's shared egress IPs are always over the daily quota.)
const ALLOW = ["/assets/", "/brownreport/", "/damngoodtrading/", "/daytradeideas/", "/devindatrader/", "/emmitttrades/", "/fearing/", "/felony_trades/", "/financialtutor/", "/gocholive/", "/hansomekelly/", "/havemercitrades/", "/jaytakeprofits/", "/lumitraders/", "/marketmovesmatt/", "/mightystocks/", "/rockstarrfx/", "/smallcapfessor/", "/thaflipking/", "/yourmoneymate/", "/yugfx/"];
const PRIVATE = new Set(["dossier.md", "offer-deck-filled.md", "README.md", "content.json"]);
const CREATORS = {"brownreport": {"name": "Jason Brown", "instagram": "brownreport"}, "damngoodtrading": {"name": "Kyle", "instagram": "damngoodtrading"}, "daytradeideas": {"name": "Jason Sen", "instagram": "daytradeideas"}, "devindatrader": {"name": "Devin Roberts", "instagram": "devindatrader"}, "emmitttrades": {"name": "Emmitt Smith", "instagram": "emmitt.trades"}, "fearing": {"name": "Fearing", "instagram": "fearingtrades"}, "felony_trades": {"name": "Conner Tyrrell", "instagram": "felony_trades"}, "financialtutor": {"name": "Kevin", "instagram": "kevinfinancialtutor"}, "gocholive": {"name": "Franklin Ovalles", "instagram": "gocholive"}, "hansomekelly": {"name": "Hansome Kelly", "instagram": "hansomekelly_"}, "havemercitrades": {"name": "Mercedith (Merci)", "instagram": "havemercitrades"}, "jaytakeprofits": {"name": "Jay Wayne", "instagram": "jaytakeprofits"}, "lumitraders": {"name": "Dasha", "instagram": "lumi_traders"}, "marketmovesmatt": {"name": "Matt Giannino", "instagram": "market.moves.matt"}, "mightystocks": {"name": "Marcelo Estrada", "instagram": "mightystocks"}, "rockstarrfx": {"name": "Rico Anderton", "instagram": "rockstarrfx"}, "smallcapfessor": {"name": "Payd", "instagram": "smallcapfessor"}, "thaflipking": {"name": "Donyell Green", "instagram": "thaflipking"}, "yourmoneymate": {"name": "Ash", "instagram": "yourmoneymateuk"}, "yugfx": {"name": "Yug Desai", "instagram": "yugfx_"}};
const PAGES = { "": "pitch page", "funnel/": "funnel page", "funnel/thank-you/": "booking page", "emails/": "email sequence", "ads/": "ad scripts" };
const BOTS = /bot|crawl|spider|slurp|preview|facebookexternalhit|facebot|whatsapp|telegram|slack|discord|skype|linkedin|pinterest|embedly|quora|vkshare|google(?:-|image|other|web)|feedfetcher|mediapartners|headless|playwright|puppeteer|lighthouse|pingdom|uptime|monitor|curl|wget|python|node-fetch|undici|axios|go-http|java\/|okhttp|http-client|scrapy|cloudflare/i;

export async function onRequest(ctx) {
  let url, path;
  try { url = new URL(ctx.request.url); path = decodeURIComponent(url.pathname); } catch { return notFound(ctx); }
  const px = path.match(/^\/o\/([a-z0-9_-]+)(?:\/([a-z]+))?\.gif$/);
  if (px) return openPixel(ctx, px[1], px[2] || "");
  const parts = path.split("/");
  const allowed = path === "/404" || path === "/404.html" || ALLOW.some(a => path === a.slice(0, -1) || path.startsWith(a));
  if (!allowed || PRIVATE.has(parts[parts.length - 1]) || parts.some(x => x.startsWith(".") || x.startsWith("_"))) return notFound(ctx);
  const res = await ctx.next();
  const at = url.searchParams.get("alerttest");
  if (at && [secret(ctx, "TELEGRAM_CHAT_ID"), discordId(ctx)].filter(Boolean).includes(at.trim())) {
    const results = await sendAlert(ctx, "✅ Visit alert self-test\nThe alerts from infooperate.com reach you.", null);
    return withHeader(res, "x-alert-result", (results.join(" | ") || "no channel configured").split("\n").join(" "));
  }
  if (url.searchParams.get("me") === "1") return withHeader(res, "set-cookie", "io_me=1; Path=/; Max-Age=31536000; Secure; SameSite=Lax");
  try { maybeNotify(ctx, url, path, res.status); } catch (e) {}
  return res;
}

// Open alerts: the outreach emails carry a 1x1 GIF at /o/{slug}/{first|followup}.gif. Gmail loads it through
// its image proxy (GoogleImageProxy) each time the email is opened with images on, so an alert means "opened",
// not "read". Caveats: Apple Mail can preload it (Mail Privacy Protection), clients that block images send
// nothing, and the owner's own look at the draft or the sent email also triggers it.
const GIF = Uint8Array.from(atob("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7"), ch => ch.charCodeAt(0));

function openPixel(ctx, slug, tag) {
  const res = new Response(GIF, { headers: { "content-type": "image/gif", "cache-control": "no-store, no-cache, must-revalidate, max-age=0", "x-robots-tag": "noindex" } });
  const c = CREATORS[slug];
  if (!c || !channels(ctx).length || ctx.request.method !== "GET") return res;
  const h = ctx.request.headers, ua = h.get("user-agent") || "";
  if (/(^|;\s*)io_me=1/.test(h.get("cookie") || "")) return res;
  const client = /googleimageproxy/i.test(ua) ? "Gmail" : /yahoo/i.test(ua) ? "Yahoo Mail" : /outlook|microsoft|office/i.test(ua) ? "Outlook" : /iphone|ipad|macintosh/i.test(ua) ? "Apple Mail (can be a preload)" : "mail app";
  const cf = ctx.request.cf || {};
  const where = client === "Gmail" ? "" : [cf.city, cf.country].filter(Boolean).join(", ");
  const text = `📬 ${c.name} opened your ${tag === "followup" ? "follow-up" : "email"}\n${slug} · ${client}${where ? " · " + where : ""}`;
  const button = c.instagram ? { text: `Open @${c.instagram} on Instagram`, url: `https://www.instagram.com/${c.instagram}/` } : null;
  ctx.waitUntil(sendAlert(ctx, text, button));
  return res;
}

function withHeader(res, name, value) {
  const r = new Response(res.body, res);
  r.headers.append(name, value);
  return r;
}

// Secrets pasted into the dashboard often carry a stray space or newline; ignore it.
function secret(ctx, name) { return ((ctx.env && ctx.env[name]) || "").trim(); }

function maybeNotify(ctx, url, path, status) {
  if (!channels(ctx).length || status !== 200 || ctx.request.method !== "GET") return;
  const m = path.match(/^\/([a-z0-9-]+)\/(.*)$/);
  if (!m || !CREATORS[m[1]] || !(m[2] in PAGES)) return;
  const h = ctx.request.headers, ua = h.get("user-agent") || "";
  if (!ua || BOTS.test(ua)) return;
  if (/(^|;\s*)io_me=1/.test(h.get("cookie") || "")) return;
  const purpose = (h.get("sec-purpose") || h.get("purpose") || h.get("x-moz") || "").toLowerCase();
  if (purpose.includes("prefetch") || purpose.includes("prerender")) return;
  const c = CREATORS[m[1]], cf = ctx.request.cf || {};
  const where = [cf.city, cf.country].filter(Boolean).join(", ") || "unknown location";
  const device = /iphone/i.test(ua) ? "iPhone" : /ipad/i.test(ua) ? "iPad" : /android/i.test(ua) ? "Android" : /macintosh/i.test(ua) ? "Mac" : /windows/i.test(ua) ? "Windows" : "other device";
  const app = /instagram/i.test(ua) ? " (Instagram app)" : /fban|fbav/i.test(ua) ? " (Facebook app)" : /gsa\//i.test(ua) ? " (Google app)" : "";
  let via = "direct / email";
  try { const ref = h.get("referer"); if (ref) { const rh = new URL(ref).hostname.replace(/^www\./, ""); via = rh === url.hostname ? "their own click on the page" : rh; } } catch (e) {}
  const text = `${m[2] === "" ? "👀" : "👉"} ${c.name} opened the ${PAGES[m[2]]}\n${m[1]} · ${where} · ${device}${app} · via ${via}`;
  const button = c.instagram ? { text: `Open @${c.instagram} on Instagram`, url: `https://www.instagram.com/${c.instagram}/` } : null;
  ctx.waitUntil(sendAlert(ctx, text, button));
}

function discordId(ctx) { const m = secret(ctx, "DISCORD_WEBHOOK_URL").match(/\/webhooks\/(\d+)\//); return m ? m[1] : ""; }

function channels(ctx) {
  const out = [];
  if (secret(ctx, "DISCORD_WEBHOOK_URL")) out.push("discord");
  if (secret(ctx, "TELEGRAM_BOT_TOKEN") && secret(ctx, "TELEGRAM_CHAT_ID")) out.push("telegram");
  return out;
}

// Sends to every configured channel; resolves to one "channel status body" string per channel, never throws.
function sendAlert(ctx, text, button) {
  return Promise.all(channels(ctx).map(async ch => {
    try {
      let r;
      if (ch === "discord") {
        const content = button ? `${text}\n<${button.url}>` : text;
        r = await fetch(secret(ctx, "DISCORD_WEBHOOK_URL"), {
          method: "POST", headers: { "content-type": "application/json" },
          body: JSON.stringify({ username: "Funnel visits", content, allowed_mentions: { parse: [] } }),
        });
      } else {
        const body = { chat_id: secret(ctx, "TELEGRAM_CHAT_ID"), text, disable_web_page_preview: true };
        if (button) body.reply_markup = { inline_keyboard: [[button]] };
        r = await fetch(`https://api.telegram.org/bot${secret(ctx, "TELEGRAM_BOT_TOKEN")}/sendMessage`, {
          method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
        });
      }
      return `${ch} ${r.status} ${(await r.text()).slice(0, 140)}`;
    } catch (e) { return `${ch} error ${e && e.message}`; }
  }));
}

async function notFound(ctx) {
  const page = await ctx.env.ASSETS.fetch(new URL("/404.html", ctx.request.url), { redirect: "follow" });
  return new Response(page.ok ? page.body : "Not found", {
    status: 404,
    headers: { "content-type": "text/html; charset=utf-8", "x-robots-tag": "noindex, nofollow" },
  });
}
